@rendermode InteractiveServer
@inject WarehouseState Warehouse
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm d-inline-block w-auto ms-2"
            @onchange="OnWarehouseChanged" value="@Warehouse.CurrentWarehouseId">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Key" selected="@(wh.Key == Warehouse.CurrentWarehouseId)">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        Warehouse.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            Warehouse.SetWarehouse(newId);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        Warehouse.OnChange -= OnStateChanged;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LowStockCount > 0)
{
    <span class="badge bg-danger ms-1" title="Low-stock items">@AlertService.LowStockCount</span>
}
else
{
    <span class="badge bg-success ms-1" title="No low-stock items">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnAlertDataChanged -= _handler;
        }
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-header">
        <h5 class="mb-0">@Warehouse.CurrentWarehouseName</h5>
    </div>
    <div class="card-body">
        <h6>Low-Stock Alerts</h6>
        <p>
            Items below minimum stock level:
            <strong class="@(AlertService.LowStockCount > 5 ? "text-danger" : "text-warning")">
                @AlertService.LowStockCount
            </strong>
        </p>
        <p class="text-muted">
            <small>Auto-refreshes every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</small>
        </p>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        // Subscribe to polling — starts the timer if this is the first subscriber.
        AlertService.Subscribe();

        _alertHandler = () => InvokeAsync(() =>
        {
            _lastUpdate = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertDataChanged += _alertHandler;

        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _warehouseHandler;
    }

    public void Dispose()
    {
        // Unsubscribe from polling — stops the timer if this is the last subscriber.
        AlertService.Unsubscribe();

        if (_alertHandler is not null)
            AlertService.OnAlertDataChanged -= _alertHandler;

        if (_warehouseHandler is not null)
            Warehouse.OnChange -= _warehouseHandler;
    }
}

